import os, json, glob, subprocess

repos = [
    "agy-os",
    "agy-research",
    "agy-root",
    "arostech-hub",
    "ECC",
    "logs_81993939307",
    "openspec",
    "agy-harness"
]

base_dir = "/mnt/d/dev"

def inspect_package_json(path):
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            data = json.load(f)
            return {
                "name": data.get("name"),
                "version": data.get("version"),
                "scripts": list(data.get("scripts", {}).keys()),
                "dependencies": list(data.get("dependencies", {}).keys()),
                "devDependencies": list(data.get("devDependencies", {}).keys()),
                "engines": data.get("engines"),
                "packageManager": data.get("packageManager")
            }
    except Exception as e:
        return {"error": str(e)}

def inspect_pyproject_toml(path):
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            content = f.read()
            return content[:500]
    except Exception as e:
        return str(e)

for repo in repos:
    rpath = os.path.join(base_dir, repo)
    print(f"\n========================================================")
    print(f"DEEP DIVE: {repo}")
    print(f"========================================================")
    if not os.path.exists(rpath):
        print("Directory does not exist.")
        continue

    # Find key files (max depth 3)
    found_files = []
    for root, dirs, files in os.walk(rpath):
        # don't traverse into node_modules or .git
        if "node_modules" in dirs:
            dirs.remove("node_modules")
        if ".git" in dirs:
            dirs.remove(".git")
        if ".venv" in dirs:
            dirs.remove(".venv")
        if ".next" in dirs:
            dirs.remove(".next")

        rel_root = os.path.relpath(root, rpath)
        depth = len(rel_root.split(os.sep)) if rel_root != "." else 0
        if depth > 4:
            continue

        for file in files:
            if file in [
                "package.json", "pyproject.toml", "Cargo.toml", "requirements.txt",
                "Dockerfile", "docker-compose.yml", "docker-compose.yaml",
                ".tool-versions", ".nvmrc", ".node-version", ".python-version",
                "wrangler.toml", "wrangler.jsonc", "prisma.schema", "schema.prisma"
            ]:
                full_p = os.path.join(root, file)
                rel_p = os.path.relpath(full_p, rpath)
                found_files.append((file, rel_p, full_p))

    print(f"Key Config Files Found ({len(found_files)}):")
    for fname, rel_p, full_p in found_files:
        print(f"  - [{fname}] {rel_p}")
        if fname == "package.json":
            info = inspect_package_json(full_p)
            print(f"      Name: {info.get('name')}, Scripts: {info.get('scripts')}")
            if info.get('dependencies'):
                print(f"      Deps ({len(info.get('dependencies'))}): {info.get('dependencies')[:8]}")
            if info.get('devDependencies'):
                print(f"      DevDeps ({len(info.get('devDependencies'))}): {info.get('devDependencies')[:8]}")
            if info.get('engines'):
                print(f"      Engines: {info.get('engines')}")
            if info.get('packageManager'):
                print(f"      PkgManager: {info.get('packageManager')}")
        elif fname in [".tool-versions", ".nvmrc", ".node-version", ".python-version"]:
            try:
                with open(full_p) as tf:
                    print(f"      Content: {tf.read().strip()}")
            except:
                pass
        elif fname == "Cargo.toml":
            try:
                with open(full_p) as cf:
                    lines = [l.strip() for l in cf.readlines() if l.strip() and not l.startswith("#")]
                    print(f"      Cargo Preview: {lines[:8]}")
            except:
                pass
        elif fname in ["schema.prisma", "prisma.schema"]:
            print(f"      Prisma Schema present.")
EOF
